import assert from 'node:assert/strict';
import {descriptorRuntime} from '../tests/helpers/native-descriptor-fixture.ts';
const bitPatterns=[0x7ff8000000000001n,0x7ff8000000000002n,0xfff8000000000001n];
const fromBits=(bits:bigint)=>{const b=new DataView(new ArrayBuffer(8));b.setBigUint64(0,bits,true);return b.getFloat64(0,true);};
const bitsOf=(value:number)=>{const b=new DataView(new ArrayBuffer(8));b.setFloat64(0,value,true);return b.getBigUint64(0,true);};
const r=descriptorRuntime(true),values=bitPatterns.map(bits=>r.boxNumber(fromBits(bits)));
assert.deepEqual(values.map(v=>bitsOf(r.unboxNumber(v))),bitPatterns);
for(let a=0;a<values.length;a++)for(let b=0;b<values.length;b++){
  const object=r.create();r.defineData(object,r.key(),values[a],128);
  let redefined=true,exception:string|undefined;
  try{r.defineData(object,r.key(),values[b],128);}catch(e){assert(e instanceof WebAssembly.Exception);assert(e.is(r.exception));redefined=false;exception='actual shared TypeError tag';}
  const host={};Object.defineProperty(host,'value',{value:fromBits(bitPatterns[a]!)});Object.defineProperty(host,'value',{value:fromBits(bitPatterns[b]!)});
  console.log(JSON.stringify({a:bitPatterns[a]!.toString(16),b:bitPatterns[b]!.toString(16),roundTripBitsRetained:true,expectedSameValue:Object.is(fromBits(bitPatterns[a]!),fromBits(bitPatterns[b]!)),sameValue:r.sameValue(values[a],values[b]),expectedRedefinition:true,redefined,exception}));
}
for(const [a,b]of [[0,-0],[-0,0],[0,0],[-0,-0],[42,42],[42,43],[Infinity,Infinity],[Infinity,-Infinity],[Number.MIN_VALUE,0]])console.log(JSON.stringify({control:[String(a),String(b)],negativeZero:[Object.is(a,-0),Object.is(b,-0)],expected:Object.is(a,b),actual:r.sameValue(r.boxNumber(a!),r.boxNumber(b!))}));
